    string s;
    cin >> s;

    int a = count(s.begin(), s.end(), 'a');
    int other = static_cast<int>(s.size()) - a;
    int denominator = min(a, other);

    cout << (denominator == 0 ? 0 : static_cast<int>(s.size()) / denominator) << '\n';
    return 0;
