#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;

    int a = 0;
    for (char c : s) {
        if (c == 'a') {
            ++a;
        }
    }

    int other = static_cast<int>(s.size()) - a;
    int divisor = min(a, other);

    cout << (divisor == 0 ? s.size() : s.size() / divisor) << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;

    int a = 0, oa = 0;
    for (char c : s) {
        if (c == 'a') ++a;
        else ++oa;
    }

    int denominator = min(a, oa);
    cout << (denominator == 0 ? 0 : static_cast<int>(s.length()) / denominator) << '\n';

    return 0;
}

